import { test, expect } from '@playwright/test';

test.describe('Share Filtered Search URL', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should successfully generate and copy a shareable URL with applied filters', async ({ page }) => {
    // Apply filters using getByRole/getByLabel
    const categoryFilter = page.getByRole('button', { name: /category/i });
    await categoryFilter.click();
    const electronicsOption = page.getByRole('option', { name: /electronics/i });
    await electronicsOption.click();

    const priceFilter = page.getByRole('button', { name: /price/i });
    await priceFilter.click();
    const priceRangeOption = page.getByRole('option', { name: /50-100/i });
    await priceRangeOption.click();

    // Verify filters are applied
    const resultsCount = page.getByText(/results found/i);
    await expect(resultsCount).toBeVisible();

    const filterTags = page.locator('[data-testid="filter-tag"]');
    await expect(filterTags).toHaveCount(2);

    // Click the share button using getByRole
    const shareButton = page.getByRole('button', { name: /share/i });
    await expect(shareButton).toBeVisible();
    await shareButton.click();

    // Verify share modal appears
    const shareModal = page.locator('[data-testid="share-modal"]');
    await expect(shareModal).toBeVisible();

    // Verify share URL is present
    const shareUrl = page.getByLabel(/shareable url/i);
    await expect(shareUrl).toBeVisible();

    // Copy the URL to clipboard
    const copyButton = page.getByRole('button', { name: /copy/i });
    await copyButton.click();

    // Verify success message
    const successMessage = page.getByText(/copied to clipboard/i);
    await expect(successMessage).toBeVisible();

    // Verify URL contains filter parameters
    const urlText = await shareUrl.textContent();
    expect(urlText).toContain('category=electronics');
    expect(urlText).toContain('price_min=50');
    expect(urlText).toContain('price_max=100');
  });

  test('should handle edge case when no filters are applied and generate a base URL', async ({ page }) => {
    // Verify initial state - no filters applied
    const filterTags = page.locator('[data-testid="filter-tag"]');
    await expect(filterTags).toHaveCount(0);

    // Click share button without applying filters
    const shareButton = page.getByRole('button', { name: /share/i });
    await shareButton.click();

    // Verify share modal appears
    const shareModal = page.locator('[data-testid="share-modal"]');
    await expect(shareModal).toBeVisible();

    // Verify share URL is generated without filter parameters
    const shareUrl = page.getByLabel(/shareable url/i);
    await expect(shareUrl).toBeVisible();

    const urlText = await shareUrl.textContent();
    expect(urlText).toContain('/search');
    expect(urlText).not.toContain('category=');
    expect(urlText).not.toContain('price_min=');

    // Copy the base URL
    const copyButton = page.getByRole('button', { name: /copy/i });
    await copyButton.click();

    // Verify success message
    const successMessage = page.getByText(/copied to clipboard/i);
    await expect(successMessage).toBeVisible();
  });
});
